example_item.example_item_data:
% Thirty seconds of simulated signal, detected with Pan and Tompkins.
recording = ecglab.simulate('Seconds', 30, 'Seed', 1);
beats = ecglab.detect(recording, 'Method', 'pantompkins');
bpm = 60 / median(beats.rr, 'omitnan')

% A consensus of two methods, keeping only the beats both agree on.
recording = ecglab.simulate('Seconds', 60, 'Noise', 0.1, 'Seed', 2);
beats = ecglab.detect(recording, 'Method', 'consensus', ...
  'Methods', {'pantompkins', 'hamilton'}, 'Votes', 2);
beats.evidence.votes
